/** fr.camera commands, as methods of an instance. */
export interface CameraClient {
  /** Starts a stream of JPEG frames (design camera-c1 D8): to the hub over HTTP (an mjpg1 POST to /v1/stream/in/<stream_id>), to the card (a recording named by the stream id), or both. Dispatch never blocks: OK once the fr_stream task has it, BUSY while another runs, INVALID_ARGS for `to` sd or both with no card mounted, or a frame_size above the trait max_frame_size. interval_ms paces by each frame's start time (0: as fast as the sensor and the path allow); seconds and max_frames end it done (0: no limit, until stream_stop). Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  streamStart(args?: CameraStreamStartArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Ends stream `stream_id` (stream_ended reason stopped); NOT_FOUND when it is not the running stream. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  streamStop(args?: CameraStreamStopArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Changes the sensor's settings now and keeps them until reboot (absent fields stay). INVALID_ARGS for a frame_size above the trait max_frame_size. A running stream takes the new settings from its next frame. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  set(args?: CameraSetArgs, opts?: CallOptions): Promise<CmdResult>;
  /** The recordings on the card, oldest first, from the `from`-th (0: the first): at most 64 per answer, `next` the index to ask for the rest (0: none left). UNSUPPORTED without a card (property sd none or error). BULK: TCP or serial, never over a gateway. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  sdList(args?: CameraSdListArgs, opts?: CallOptions): Promise<CmdResult<CameraSdListResult>>;
  /** Streams recording `recording`'s frames to the hub as an mjpg1 stream (flags b0 set), from frame `from_frame`; ends done after the last. BUSY while a stream runs; NOT_FOUND for a recording not on the card; UNSUPPORTED without a card. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  sdFetch(args?: CameraSdFetchArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Removes recording `recording` from the card (its directory and frames); OK when it is already gone. UNSUPPORTED without a card; BUSY while a stream writes to or reads from it. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  sdDelete(args?: CameraSdDeleteArgs, opts?: CallOptions): Promise<CmdResult>;
}

/** fr.camera.stream_ended event fields (normal). A stream (or sd_fetch) ended: stopped (stream_stop), done (`seconds` or `max_frames` reached), net_lost (a send stalled 3 s or the connection dropped), overflow (the card is full or failed mid-stream), error (the sensor failed). */
export interface CameraStreamEndedFields {
  streamId: number;
  reason: CameraStreamEndReason | number;
  /** frames the stream covered, dropped ones included (the index it reached) */
  frames: number;
  /** frames the sensor delivered that the stream could not take (the hub path behind) */
  dropped: number;
  /** JPEG bytes sent and/or written */
  bytes: number;
}

/** fr.camera events by wire name: `pad.on('<inst>.<event>', e => ...)`. */
export interface CameraEvents {
  stream_ended: CameraStreamEndedFields;
}

/** fr.camera properties as the mirror holds them (`pad.<inst>.state`); a property a trait gates may be absent. */
export interface CameraState {
  /** frames captured since boot */
  frames: number;
  /** frames per second over the last second, x10 (0 while idle) */
  fpsX10: number;
  /** the last frame's JPEG bytes */
  lastBytes: number;
  /** a stream (or an sd_fetch) runs */
  streaming: boolean;
  /** the card: none (no card, or config sd false), mounted, error (mount or write failed) */
  sd: CameraCardState | number;
  /** free space on the card; 0 when none (MB) */
  sdFreeMb: number;
}

/** fr.camera property values by wire name: what a `<inst>.<prop>` event carries as `value`. */
export interface CameraProps {
  frames: number;
  fps_x10: number;
  last_bytes: number;
  streaming: boolean;
  sd: CameraCardState | number;
  sd_free_mb: number;
}

// ---- fr.node ----

/** fr.node.identify arguments (all optional: the device applies the defaults). */
export interface NodeIdentifyArgs {
  /** (default 3000) */
  ms?: number;
}

/** fr.node.describe RESULT fields. */
export interface NodeDescribeResult {
  /** a protobuf-wire Descriptor (schema/protocol.yaml types) (hex, <= 1200 bytes) */
  descriptor: string;
}

/** fr.node.reboot arguments (all optional: the device applies the defaults). */
export interface NodeRebootArgs {
  /** (default false) */
  bootloader?: boolean;
}

/** fr.node.set_alias arguments (all optional: the device applies the defaults). */
export interface NodeSetAliasArgs {
  /** (<= 31 UTF-8 bytes) */
  alias?: string;
  rev?: number;
}

/** fr.node.set_groups arguments (all optional: the device applies the defaults). */
export interface NodeSetGroupsArgs {
  /** (<= 8 items) */
  groups?: readonly number[];
}

/** fr.node.net_set arguments (all optional: the device applies the defaults). */
export interface NodeNetSetArgs {
  /** (<= 32 UTF-8 bytes) */
  ssid?: string;
  /** (<= 64 UTF-8 bytes) */
  pass?: string;
  /** (hex, <= 6 bytes) */
  bssid?: string;
  /** (<= 32 UTF-8 bytes) */
  hubHost?: string;
}

/** fr.node.bind_set arguments (all optional: the device applies the defaults). */
export interface NodeBindSetArgs {
  /** (0..15) */
  slot?: number;
  onPort?: number;
  /** 3 EVENT | 7 MSG */
  onCls?: number;
  /** the event id (EVENT) */
  onKind?: number;
  /** the MSG topic (MSG) (<= 32 UTF-8 bytes) */
  onTopic?: string;
  /** (hex, <= 6 bytes) */
  toMac?: string;
  /** this node, another node, or 0xFFFF (MSG broadcast) */
  toAddr?: number;
  toPort?: number;
  /** 4 CMD | 7 MSG */
  toCls?: number;
  /** the command id (CMD) */
  toKind?: number;
  /** the MSG topic (MSG) (<= 32 UTF-8 bytes) */
  toTopic?: string;
  /** pre-encoded CMD fields, or the MSG data (hex, <= 64 bytes) */
  payload?: string;
  /** Q1: ACK_REQ, the target's RESULT or ACK, end-to-end retries */
  reliable?: boolean;
}

/** fr.node.bind_clear arguments (all optional: the device applies the defaults). */
export interface NodeBindClearArgs {
  /** 0..15, or 255: every slot */
  slot?: number;
}

/** fr.node.bind_list RESULT fields. */
export interface NodeBindListResult {
  /** a protobuf-wire BindingList (schema/protocol.yaml types) (hex, <= 1400 bytes) */
  bindings: string;
}

/** fr.node commands, as methods of an instance. */
export interface NodeClient {
  /** Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  identify(args?: NodeIdentifyArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Returns the node descriptor (07 §7.4), encoded; HELLO descriptor_hash is FNV-1a 32 over it. BULK: TCP or serial only. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  describe(opts?: CallOptions): Promise<CmdResult<NodeDescribeResult>>;
  /** Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  reboot(args?: NodeRebootArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  setAlias(args?: NodeSetAliasArgs, opts?: CallOptions): Promise<CmdResult>;
  /** M2 Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  setGroups(args?: NodeSetGroupsArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  netSet(args?: NodeNetSetArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Re-send every property with fresh LATEST seqs. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  getState(opts?: CallOptions): Promise<CmdResult>;
  /** Store a binding in its slot (07 §7.11), replacing what the slot held; the hub resolves and pre-encodes it. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  bindSet(args?: NodeBindSetArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  bindClear(args?: NodeBindClearArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Returns the stored bindings, encoded (like describe). BULK: TCP or serial only. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  bindList(opts?: CallOptions): Promise<CmdResult<NodeBindListResult>>;
}

/** fr.node.boot event fields (normal). Sent once per boot right after the first WELCOME; exempt from the event-age rule. */
export interface NodeBootFields {
  resetReason: number;
}

/** fr.node.binding_fired event fields (normal). */
export interface NodeBindingFiredFields {
  slot: number;
  /** the target's RESULT/ACK status for reliable sends; 0 for fast, MSG and broadcast; FAILED after the last attempt; BUSY with no path */
  targetStatus: number;
  /** trigger -> target RESULT; 0 for fast commands */
  rttUs: number;
  /** 0 espnow, 1 hub, 2 flood, 3 local (the node itself) */
  path: number;
}

/** fr.node events by wire name: `pad.on('<inst>.<event>', e => ...)`. */
export interface NodeEvents {
  boot: NodeBootFields;
  binding_fired: NodeBindingFiredFields;
}

/** fr.node properties as the mirror holds them (`pad.<inst>.state`); a property a trait gates may be absent. */
export interface NodeState {}

/** fr.node property values by wire name: what a `<inst>.<prop>` event carries as `value`. */
export interface NodeProps {}

